               '𝟱. 𝗚𝗨𝗔𝗥𝗗𝗥𝗔𝗜𝗟𝗦\n'
               '• The same safety stack as Argon, tightened\n'
               "• 0.0% prompt-injection success in Google's tests\n"
               '• 80% fewer serious misalignment alerts, and half the unsupported claims\n'
               '\n'
               '𝟲. 𝗥𝗢𝗟𝗟𝗢𝗨𝗧 𝗔𝗡𝗗 𝗣𝗥𝗜𝗖𝗘\n'
               '• Not public yet: US government testing first, then cyber defenders, then 650+ '
