               '• Launch price: $2 / $10 per million tokens, 50% off until the end of 2026\n'
               '\n'
               '𝗪𝗵𝗮𝘁 𝘁𝗵𝗶𝘀 𝗺𝗲𝗮𝗻𝘀 𝗳𝗼𝗿 𝗯𝘂𝘀𝗶𝗻𝗲𝘀𝘀𝗲𝘀\n'
