               '• The sample uses Model Armor-style regex filtering and OPA-style local checks—not '
               'full service integrations. \n'
               '\n'
               '📊 𝙍𝙚𝙨𝙪𝙡𝙩𝙨 𝙞𝙣 𝙘𝙤𝙣𝙩𝙚𝙭𝙩 \n'
