               'out framework overhead without breaking any existing app, then let it run '
               'overnight.\n'
               '\n'
               'By morning, session prep in long conversations was 40% faster and cold imports '
               'were 21% faster. Those changes are merged into adk-python today.\n'
               '\n'
               'Across Google, Argon in Antigravity has lifted agentic code submissions by more '
               'than 35% while cutting rollbacks by nearly a third.\n'
